use std::env;

#[derive(Debug, Clone)]
pub struct Args {
    pub version: bool,
    pub help: bool,
    pub pager: Option<String>,
    pub color_only: bool,
    pub dark: bool,
    pub light: bool,
}

pub fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();

    let mut parsed = Args {
        version: false,
        help: false,
        pager: None,
        color_only: false,
        dark: false,
        light: false,
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" => parsed.version = true,
            "--help" | "-h" => parsed.help = true,
            "--color-only" => parsed.color_only = true,
            "--dark" => parsed.dark = true,
            "--light" => parsed.light = true,
            "--pager" => {
                if i + 1 < args.len() {
                    parsed.pager = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            arg if arg.starts_with("--pager=") => {
                parsed.pager = Some(arg[8..].to_string());
            }
            _ => {}
        }
        i += 1;
    }

    parsed
}
EOF

