use std::io::{self, Read};
use std::env;
use std::process;
use std::fs;

mod cli;
mod diff_parser;
mod formatter;

use cli::Args;

fn main() {
    let args = cli::parse_args();

    // Handle special info flags
    if args.version {
        println!("delta 0.18.2");
        return;
    }

    if args.help {
        print_help();
        return;
    }

    // Get input based on arguments
    let input = if let (Some(file1), Some(file2)) = (&args.file1, &args.file2) {
        // Generate diff from two files
        generate_diff(file1, file2)
    } else if args.file1.is_some() && args.file2.is_none() {
        // Error: only one file provided
        eprintln!("Error: expected two files or pipe diff via stdin");
        process::exit(1);
    } else {
        // Read from stdin
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_err() {
            eprintln!("Error reading input");
            process::exit(1);
        }
        buffer
    };

    // Parse diff
    let diff = diff_parser::parse_diff(&input);

    // Format output
    let formatted = formatter::format_diff(&diff, &args);
    print!("{}", formatted);
}

fn generate_diff(file1: &str, file2: &str) -> String {
    let content1 = fs::read_to_string(file1).unwrap_or_default();
    let content2 = fs::read_to_string(file2).unwrap_or_default();

    // Generate unified diff
    let mut diff_output = String::new();
    diff_output.push_str(&format!("--- {}\n", file1));
    diff_output.push_str(&format!("+++ {}\n", file2));

    // Simple line-by-line diff
    let lines1: Vec<&str> = content1.lines().collect();
    let lines2: Vec<&str> = content2.lines().collect();

    // For now, output a simple diff
    diff_output.push_str("@@ -1,");
    diff_output.push_str(&lines1.len().to_string());
    diff_output.push_str(" +1,");
    diff_output.push_str(&lines2.len().to_string());
    diff_output.push_str(" @@\n");

    // Simple diff logic - this is very basic
    let max_lines = lines1.len().max(lines2.len());
    for i in 0..max_lines {
        if i < lines1.len() && i < lines2.len() {
            if lines1[i] == lines2[i] {
                diff_output.push_str(" ");
                diff_output.push_str(lines1[i]);
                diff_output.push('\n');
            } else {
                diff_output.push_str("-");
                diff_output.push_str(lines1[i]);
                diff_output.push('\n');
                diff_output.push_str("+");
                diff_output.push_str(lines2[i]);
                diff_output.push('\n');
            }
        } else if i < lines1.len() {
            diff_output.push_str("-");
            diff_output.push_str(lines1[i]);
            diff_output.push('\n');
        } else {
            diff_output.push_str("+");
            diff_output.push_str(lines2[i]);
            diff_output.push('\n');
        }
    }

    diff_output
}

fn print_help() {
    println!("A viewer for git and diff output");
    println!("");
    println!("Usage: delta [OPTIONS] [MINUS_FILE] [PLUS_FILE]");
}
