use crate::cli::Args;
use crate::diff_parser::{Diff, DiffLine};

pub fn format_diff(diff: &Diff, _args: &Args) -> String {
    let mut output = String::new();

    // Colors (ANSI codes)
    let blue = "\x1b[34m";
    let reset = "\x1b[0m";
    let light_gray = "\x1b[38;5;231m";
    let dark_red_bg = "\x1b[48;5;52m";
    let dark_green_bg = "\x1b[48;5;22m";
    let red_highlight = "\x1b[48;5;124m";
    let green_highlight = "\x1b[48;5;28m";
    let clear_to_eol = "\x1b[0K";

    // Box drawing characters
    let dash = "─";
    let top_right = "┐";
    let vertical = "│";
    let arrow = "⟶";
    let bottom_right = "┘";

    for hunk in &diff.hunks {
        // Output file header
        if !hunk.old_file.is_empty() && !hunk.new_file.is_empty() {
            output.push('\n');
            output.push_str(&format!("{}{} {}   {}{}\n", blue, hunk.old_file, arrow, hunk.new_file, reset));

            // Separator line (80 dashes)
            let sep_line = dash.repeat(80);
            output.push_str(&format!("{}{}{}\n", blue, sep_line, reset));
            output.push('\n');

            // Line number box - top
            let mut top_line = String::new();
            top_line.push_str(blue);
            top_line.push_str(dash);
            top_line.push_str(dash);
            top_line.push_str(dash);
            top_line.push_str(top_right);
            top_line.push_str(reset);
            output.push_str(&top_line);
            output.push('\n');

            // Line number box - middle
            let mut mid_line = String::new();
            mid_line.push_str(blue);
            mid_line.push('1');
            mid_line.push_str(reset);
            mid_line.push(':');
            mid_line.push(' ');
            mid_line.push_str(blue);
            mid_line.push_str(vertical);
            mid_line.push_str(reset);
            output.push_str(&mid_line);
            output.push('\n');

            // Line number box - bottom
            let mut bot_line = String::new();
            bot_line.push_str(blue);
            bot_line.push_str(dash);
            bot_line.push_str(dash);
            bot_line.push_str(dash);
            bot_line.push_str(bottom_right);
            bot_line.push_str(reset);
            output.push_str(&bot_line);
            output.push('\n');
        }

        // Output lines
        for line in &hunk.lines {
            match line {
                DiffLine::Header(_) => {
                    // Skip hunk headers for now
                }
                DiffLine::Context(text) => {
                    output.push_str(&format!("{}{}{}\n", light_gray, text, reset));
                }
                DiffLine::Removed(text) => {
                    output.push_str(&format!("{}{}{}{}{}\n", dark_red_bg, text, reset, dark_red_bg, clear_to_eol));
                }
                DiffLine::Added(text) => {
                    output.push_str(&format!("{}{}{}{}{}\n", dark_green_bg, light_gray, text, reset, clear_to_eol));
                }
                DiffLine::RemovedWithHighlight(segments) => {
                    output.push_str(dark_red_bg);
                    for seg in segments {
                        if seg.highlighted {
                            output.push_str(red_highlight);
                        } else {
                            output.push_str(dark_red_bg);
                        }
                        output.push_str(&seg.text);
                        if seg.highlighted {
                            output.push_str(reset);
                            output.push_str(dark_red_bg);
                        }
                        output.push(' ');
                    }
                    // Remove trailing space
                    if output.ends_with(' ') {
                        output.pop();
                    }
                    output.push_str(reset);
                    output.push_str(dark_red_bg);
                    output.push_str(clear_to_eol);
                    output.push_str(reset);
                    output.push('\n');
                }
                DiffLine::AddedWithHighlight(segments) => {
                    output.push_str(dark_green_bg);
                    output.push_str(light_gray);
                    for seg in segments {
                        if seg.highlighted {
                            output.push_str(green_highlight);
                        } else {
                            output.push_str(dark_green_bg);
                        }
                        output.push_str(&seg.text);
                        if seg.highlighted {
                            output.push_str(reset);
                            output.push_str(dark_green_bg);
                            output.push_str(light_gray);
                        }
                        output.push(' ');
                    }
                    // Remove trailing space
                    if output.ends_with(' ') {
                        output.pop();
                    }
                    output.push_str(reset);
                    output.push_str(clear_to_eol);
                    output.push_str(reset);
                    output.push('\n');
                }
                DiffLine::Info(_) => {}
            }
        }
    }

    output
}
EOF

