        if io::stdin().read_to_string(&mut buffer).is_err() {
            eprintln!("Error reading input");
            process::exit(1);
        }
        buffer
    };

    // Parse diff
    let diff = diff_parser::parse_diff(&input);

    // Format output
    let formatted = formatter::format_diff(&diff, &args);
    print!("{}", formatted);
}

