/// Simple word-level diffing using a basic algorithm
/// Returns pairs of (removed_highlights, added_highlights)

pub struct WordDiffResult {
    pub removed: Vec<WordSegment>,
    pub added: Vec<WordSegment>,
}

#[derive(Debug, Clone)]
pub struct WordSegment {
    pub text: String,
    pub highlighted: bool,
}

/// Perform simple word-level diff
pub fn diff_lines(removed_line: &str, added_line: &str) -> WordDiffResult {
    let removed_words: Vec<&str> = removed_line.split_whitespace().collect();
    let added_words: Vec<&str> = added_line.split_whitespace().collect();

    // For now, just do a simple matching
    let mut removed_segments = Vec::new();
    let mut added_segments = Vec::new();

    // Simple algorithm: match words
    for (i, &word) in removed_words.iter().enumerate() {
        let other_word = added_words.get(i).copied().unwrap_or("");
        let highlighted = word != other_word;
        removed_segments.push(WordSegment {
            text: word.to_string(),
            highlighted,
        });
    }

    for (i, &word) in added_words.iter().enumerate() {
        let other_word = removed_words.get(i).copied().unwrap_or("");
        let highlighted = word != other_word;
        added_segments.push(WordSegment {
            text: word.to_string(),
            highlighted,
        });
    }

    WordDiffResult {
        removed: removed_segments,
        added: added_segments,
    }
}
