                    output.push_str(&format!("{}{}{}{}{}\n", dark_green_bg, light_gray, text, reset, clear_to_eol));
                }
                DiffLine::RemovedWithHighlight(segments) => {
                    output.push_str(dark_red_bg);
                    for (idx, seg) in segments.iter().enumerate() {
                        if seg.highlighted {
                            output.push_str(red_highlight);
                        }
                        output.push_str(&seg.text);
                        if seg.highlighted {
                            output.push_str(reset);
                            output.push_str(dark_red_bg);
                        }
                        if idx < segments.len() - 1 {
                            output.push(' ');
                        }
                    }
                    output.push_str(reset);
                    output.push_str(dark_red_bg);
                    output.push_str(clear_to_eol);
                    output.push_str(reset);
                    output.push('\n');
                }
