use crate::word_diff::diff_lines;

#[derive(Debug, Clone)]
pub struct Diff {
    pub hunks: Vec<Hunk>,
}

#[derive(Debug, Clone)]
pub struct Hunk {
    pub old_file: String,
    pub new_file: String,
    pub lines: Vec<DiffLine>,
}

#[derive(Debug, Clone)]
pub enum DiffLine {
    Context(String),
    Removed(String),
    Added(String),
    RemovedWithHighlight(Vec<crate::word_diff::WordSegment>),
    AddedWithHighlight(Vec<crate::word_diff::WordSegment>),
    Header(String),
    Info(String),
}

pub fn parse_diff(input: &str) -> Diff {
    let mut hunks = Vec::new();
    let mut current_hunk_lines = Vec::new();
    let mut old_file = String::new();
    let mut new_file = String::new();
    let mut in_hunk = false;

    // First pass: collect lines
    let mut raw_lines = Vec::new();
    for line in input.lines() {
        raw_lines.push(line.to_string());
    }

    let mut i = 0;
    while i < raw_lines.len() {
        let line = &raw_lines[i];

        if line.starts_with("--- ") {
            old_file = line[4..].to_string();
            old_file = old_file.split('\t').next().unwrap_or(&old_file).to_string();
        } else if line.starts_with("+++ ") {
            new_file = line[4..].to_string();
            new_file = new_file.split('\t').next().unwrap_or(&new_file).to_string();
        } else if line.starts_with("@@") || line.starts_with("+++") {
            // Hunk header (could be @@...@@ or @@@...@@@ for merges)
            if !current_hunk_lines.is_empty() && in_hunk {
                hunks.push(Hunk {
                    old_file: old_file.clone(),
                    new_file: new_file.clone(),
                    lines: current_hunk_lines.clone(),
                });
                current_hunk_lines.clear();
            }
            in_hunk = true;
            if !line.starts_with("+++") {  // Skip diff headers
                current_hunk_lines.push(DiffLine::Header(line.to_string()));
            }
        } else if in_hunk {
            if line.starts_with('-') && !line.starts_with("---") {
                // Look ahead to see if next line is an addition
                if i + 1 < raw_lines.len() && raw_lines[i + 1].starts_with('+') && !raw_lines[i + 1].starts_with("+++") {
                    let removed = line[1..].to_string();
                    let added = raw_lines[i + 1][1..].to_string();

                    // Do word-level diff
                    let word_diff = diff_lines(&removed, &added);
                    current_hunk_lines.push(DiffLine::RemovedWithHighlight(word_diff.removed));
                    current_hunk_lines.push(DiffLine::AddedWithHighlight(word_diff.added));
                    i += 1; // Skip the next line
                } else {
                    current_hunk_lines.push(DiffLine::Removed(line[1..].to_string()));
                }
            } else if line.starts_with('+') && !line.starts_with("+++") {
                current_hunk_lines.push(DiffLine::Added(line[1..].to_string()));
            } else if line.starts_with(' ') {
                current_hunk_lines.push(DiffLine::Context(line[1..].to_string()));
            } else if line.starts_with('\\') {
                current_hunk_lines.push(DiffLine::Info(line.to_string()));
            } else if line.starts_with("<<<<<<") || line.starts_with("======") || line.starts_with(">>>>>>>") || line.starts_with("|||||") {
                // Merge conflict markers - treat as context for now
                current_hunk_lines.push(DiffLine::Context(line.to_string()));
            }
        } else {
            current_hunk_lines.push(DiffLine::Header(line.to_string()));
        }
        i += 1;
    }

    if !current_hunk_lines.is_empty() && in_hunk {
        hunks.push(Hunk {
            old_file: old_file.clone(),
            new_file: new_file.clone(),
            lines: current_hunk_lines,
        });
    }

    Diff { hunks }
}
EOF

