use std::env;

#[derive(Debug, Clone)]
pub struct Args {
    pub version: bool,
    pub help: bool,
    pub pager: Option<String>,
    pub color_only: bool,
    pub dark: bool,
    pub light: bool,
    pub file1: Option<String>,
    pub file2: Option<String>,
    pub list_languages: bool,
    pub list_syntax_themes: bool,
}

pub fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();

    let mut parsed = Args {
        version: false,
        help: false,
        pager: None,
        color_only: false,
        dark: false,
        light: false,
        file1: None,
        file2: None,
        list_languages: false,
        list_syntax_themes: false,
    };

    let mut positional_count = 0;
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" => parsed.version = true,
            "--help" | "-h" => parsed.help = true,
            "--color-only" => parsed.color_only = true,
            "--dark" => parsed.dark = true,
            "--light" => parsed.light = true,
            "--list-languages" => parsed.list_languages = true,
            "--list-syntax-themes" => parsed.list_syntax_themes = true,
            "--pager" => {
                if i + 1 < args.len() {
                    parsed.pager = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            arg if arg.starts_with("--pager=") => {
                parsed.pager = Some(arg[8..].to_string());
            }
            arg if !arg.starts_with("-") => {
                if positional_count == 0 {
                    parsed.file1 = Some(arg.to_string());
                    positional_count += 1;
                } else if positional_count == 1 {
                    parsed.file2 = Some(arg.to_string());
                    positional_count += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }

    parsed
}
